VALUES (@level_id,'EN-A1-L-0071',71,'My own book','کتاب خودم','با own یک کاربرد کوتاه و طبیعی را تمرین کن.','EN-A1-OUTCOME-0071',420,'3c692c73cc31871c456a24e420e005ff07b95f83dc2582585001e6a6c2683467','validated','{"outcomeFa":"own را برای چیزی که متعلق به خودت است به کار ببری.","scenarioFa":"اوون و نورا کتاب‌های روی میز را جدا می‌کنند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0070"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0071-OWN","form":"This is my own book","meaningFa":"گفتن این که کتاب متعلق به خودت است"}],"supportLanguage":[{"form":"Whose book is this?","meaningFa":"این کتاب مال کیست؟"},{"form":"And that book?","meaningFa":"و آن کتاب؟"}],"assessmentBoundary":"Only own after a possessive in the bounded belonging sense is assessed.","transferPlan":{"mode":"same_lesson","intent":"Change possessor and demonstrative while keeping own stable."},"story":{"arcKey":"EN-A1-NEIGHBORS","sceneKey":"EN-A1-FACTORY-SCENE-0071","learnerRoleKey":"owen","participants":["owen","nora"],"introducedCharacterKeys":[],"relationshipState":"already_known","dependsOnLessonKeys":["EN-A1-L-0064"],"continuesLessonKey":"EN-A1-L-0064","settingFa":"خانه، کنار میز","storyBeatFa":"اوون و نورا کتاب‌های خودشان را جدا می‌کنند."},"reviewLinks":[{"lessonKey":"EN-A1-L-0064","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning arc is spaced by seven Lessons and the learner role is rotated."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0071","specHash":"ad1c8a2139d96067d143dab52ad14d2505d8a8069f0001845dca5509a7187a13","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"your own use","rationale":"Selected reference example confirms own after a possessive."},{"query":"is my own book","rationale":"Exact target-collocation window generated around own in the first learner response."},{"query":"is your own book","rationale":"Exact target-collocation window generated around own in the changed-context learner response."}],"noNewGrammarReason":"Lexical-focus Lesson using familiar be, possessives and demonstratives."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing","qualityV2Remediated":true,"qualityV2RemediationVersion":1,"qualityV2Polished":true,"qualityV2PolishVersion":2}')
